def quitar_validacion(apps, schema_editor):
    """El JSON Schema anterior no permite los campos nuevos: se quita mientras se
    migra y luego se vuelve a aplicar con json_schema/validaciones.js."""
    db = schema_editor.connection.connection
    if 'facturas' in db.list_collection_names():
        db.command('collMod', 'facturas', validator={}, validationLevel='off')


def completar_facturas_existentes(apps, schema_editor):
    """Facturas creadas antes de esta versión: el subtotal pasa a ser el ítem del
    vehículo, se guarda el % de IVA y se enlaza la cotización vendida."""
    db = schema_editor.connection.connection
    cotizaciones = {}
    for cotizacion in db['cotizaciones'].find({'venta.numero_factura': {'$nin': ['', None]}}):
        cotizaciones[cotizacion['venta']['numero_factura']] = cotizacion.get('id')
    for factura in db['facturas'].find():
        cambios = {}
        if not factura.get('items'):
            cambios['items'] = [{
                'concepto': 'vehiculo',
                'descripcion': 'Vehículo ' + factura.get('placa_vehiculo', ''),
                'cantidad': 1,
                'valor_unitario': float(factura.get('subtotal') or 0),
            }]
        if 'cuotas' not in factura:
            cambios['cuotas'] = []
        if 'anulacion' not in factura:
            cambios['anulacion'] = None
        if factura.get('id_cotizacion') is None:
            cambios['id_cotizacion'] = cotizaciones.get(factura.get('numero_factura'))
        subtotal = factura.get('subtotal') or 0
        if 'iva_porcentaje' not in factura or (subtotal and factura.get('iva_porcentaje') == 19):
            cambios['iva_porcentaje'] = round(factura.get('impuesto_iva', 0) * 100 / subtotal, 2) if subtotal else 19.0
        if cambios:
            db['facturas'].update_one({'_id': factura['_id']}, {'$set': cambios},
                                      bypass_document_validation=True)


